<?php $this->view('page_components/header'); ?>
<div class="page-heading"><div class="page-title"><h3><?= !empty($archiveDocumentLabel) ? 'Archiwum dokumentów ' . htmlspecialchars($archiveDocumentLabel) : 'Wysyłki (wygenerowane)' ?></h3></div>
<section class="section"><div class="card"><div class="card-body">
    <div class="row mb-3"><div class="col-md-4"><input class="form-control" id="filterCompany" placeholder="Filtruj po nazwie klienta"></div><div class="col-md-3"><input class="form-control" type="date" id="filterDate"></div><div class="col-md-2"><button class="btn btn-outline-secondary w-100" type="button" onclick="clearFilters()">Wyczyść</button></div><div class="col-md-3"><button class="btn btn-outline-primary w-100" id="refresh-ksef-statuses" type="button" onclick="refreshKsefStatuses(true)"><i class="bi bi-arrow-clockwise"></i> Odśwież statusy KSeF</button></div></div>
    <div class="table-responsive"><table class="table table-hover" id="generatedDocsTable"><thead><tr><th>Data</th><th>Klient</th><?php if (empty($archiveDocumentType)): ?><th></th><th></th><th></th><th></th><th></th><th></th><th>KSeF</th><?php else: ?><th>Dokument</th><?php endif; ?></tr></thead><tbody>
    <?php foreach ($generated_docs ?? [] as $row): ?><tr><td><?= htmlspecialchars($row['shipment_date']) ?></td><td><?= htmlspecialchars($row['company']) ?></td>
    <?php if (empty($archiveDocumentType)): ?>
        <td><button class="btn btn-outline-dark" onclick="getCMR(<?= (int)$row['id_cmr'] ?>)" type="button">CMR<br>[PDF]</button></td><td><button class="btn btn-info" onclick="getGrouped(<?= (int)$row['id'] ?>)" type="button">Dokumenty<br>[PDF]</button></td><td><button class="btn btn-danger" onclick="getWDT(<?= (int)$row['id_wdt'] ?>)" type="button">WDT<br>[PDF]</button></td><td><?php if ((int)$row['id_diff'] !== 0): ?><button class="btn btn-primary" onclick="getDiff(<?= (int)$row['id_diff'] ?>)" type="button">Różnice<br>[PDF]</button><?php endif; ?></td><td><?php if (($row['ksef_status'] ?? null) !== 'accepted'): ?><a href="<?= ROOT ?>/wdt-documents/<?= (int)$row['id_wdt'] ?>/products" class="btn btn-warning" data-ksef-edit-prices="<?= (int)$row['id'] ?>">Edytuj ceny</a><?php endif; ?></td><td><button class="btn btn-secondary" onclick="sendToFranchisee(<?= (int)$row['id_wdt'] ?>)" type="button">Prześlij<br>do franczyzy</button></td><td><?php $status = $row['ksef_status'] ?? null; ?><?php if ($status !== 'accepted'): ?><button class="btn btn-sm btn-outline-primary mb-1" data-ksef-send-button="<?= (int)$row['id'] ?>" onclick="sendToKsef(<?= (int)$row['id'] ?>)" type="button" <?= $status === 'processing' ? 'disabled' : '' ?>>Wyślij KSeF</button><br><?php endif; ?><span class="badge bg-light text-dark border border-secondary" data-ksef-status="<?= (int)$row['id'] ?>"><?= htmlspecialchars($status ?? 'nie wysłano') ?></span><div class="small mt-1 text-muted" data-ksef-number="<?= (int)$row['id'] ?>"><?= !empty($row['ksef_number']) ? htmlspecialchars($row['ksef_number']) : '' ?></div><div data-ksef-upo="<?= (int)$row['id'] ?>"><?php if (!empty($row['ksef_upo_available'])): ?><a class="btn btn-sm btn-outline-secondary mt-1" href="<?= ROOT ?>/ajax/shipments/<?= (int)$row['id'] ?>/ksef/upo">Pobierz UPO</a><?php endif; ?></div></td>
    <?php else: ?><td><?php if ($archiveDocumentType === 'wz'): ?><button class="btn btn-sm btn-outline-secondary" onclick="getGrouped(<?= (int)$row['id'] ?>)" type="button">WZ PDF</button><?php elseif ($archiveDocumentType === 'cmr'): ?><button class="btn btn-sm btn-outline-dark" onclick="getCMR(<?= (int)$row['id_cmr'] ?>)" type="button">CMR PDF</button><?php elseif ($archiveDocumentType === 'wdt'): ?><button class="btn btn-sm btn-outline-danger" onclick="getWDT(<?= (int)$row['id_wdt'] ?>)" type="button">WDT PDF</button><?php else: ?><button class="btn btn-sm btn-outline-primary" onclick="getDiff(<?= (int)$row['id_diff'] ?>)" type="button">Różnice PDF</button><?php endif; ?></td><?php endif; ?></tr><?php endforeach; ?>
    </tbody></table></div></div></div></section></div>
<?php $this->view('page_components/footer'); ?>
<script>
function getCMR(id) { downloadPDF('/ajax/cmr-documents/' + id + '/document'); } function getGrouped(id) { downloadPDF('/ajax/shipments/' + id + '/documents/grouped'); } function getWDT(id) { downloadPDF('/ajax/wdt-documents/' + id + '/document'); } function getDiff(id) { downloadPDF('/ajax/difference-documents/' + id + '/document'); }
function sendToFranchisee(id_wdt) { getJSON(validAjaxUrl() + 'ajax/wdt/send_to_franchisee', 'data=' + JSON.stringify({id_wdt})).then(showSnack); }
function updateKsefStatus(shipmentId, submission) { const status=document.querySelector(`[data-ksef-status="${shipmentId}"]`), number=document.querySelector(`[data-ksef-number="${shipmentId}"]`), send=document.querySelector(`[data-ksef-send-button="${shipmentId}"]`), edit=document.querySelector(`[data-ksef-edit-prices="${shipmentId}"]`), upo=document.querySelector(`[data-ksef-upo="${shipmentId}"]`); if(status) status.textContent=submission.status || 'nie wysłano'; if(number) number.textContent=submission.ksef_number || ''; if(upo && submission.upo_available) upo.innerHTML=`<a class="btn btn-sm btn-outline-secondary mt-1" href="<?= ROOT ?>/ajax/shipments/${shipmentId}/ksef/upo">Pobierz UPO</a>`; if(submission.status === 'accepted') { if(send) send.remove(); if(edit) edit.remove(); } else if(send) send.disabled=submission.status === 'processing'; }
function showKsefLoading() { if (typeof Swal !== 'undefined') Swal.fire({title:'Wysyłanie faktury do KSeF', text:'Trwa uwierzytelnianie i przekazywanie faktury. Nie zamykaj tego okna.', allowOutsideClick:false, allowEscapeKey:false, didOpen:()=>Swal.showLoading()}); }
async function confirmKsefSend() { if (typeof Swal === 'undefined') return confirm('Wysłać tę fakturę WDT do KSeF?'); const result=await Swal.fire({title:'Wysłać fakturę do KSeF?', text:'Faktura zostanie przekazana do przetwarzania w wybranym środowisku KSeF.', icon:'question', showCancelButton:true, confirmButtonText:'Wyślij do KSeF', cancelButtonText:'Anuluj', reverseButtons:true}); return result.isConfirmed; }
async function sendToKsef(id) { if (!await confirmKsefSend()) return; showKsefLoading(); try { const r=await fetch('<?= ROOT ?>/ajax/shipments/'+id+'/ksef/send',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:'{}'}); const d=await r.json(); if(!r.ok||!d.ok) throw new Error(d.message); updateKsefStatus(id,d.submission); showSnack(true,d.message); window.setTimeout(() => refreshKsefStatuses(false), 5000); } catch(e) { showSnack(false,e.message); } finally { if(typeof Swal !== 'undefined') Swal.close(); } }
async function refreshKsefStatuses(showResult=false) { const button=document.getElementById('refresh-ksef-statuses'); if(button) button.disabled=true; try { const r=await fetch('<?= ROOT ?>/ajax/shipments/ksef/refresh-statuses',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:'{}'}); const d=await r.json(); if(!r.ok||!d.ok) throw new Error(d.message); const x=d.result; (x.updates || []).forEach(item => updateKsefStatus(item.shipmentId,item.submission)); if(showResult) showSnack(true, `Sprawdzono: ${x.checked}; przyjęto: ${x.accepted}; odrzucono: ${x.rejected}; oczekuje: ${x.pending}.`); } catch(e) { if(showResult) showSnack(false,e.message); } finally { if(button) button.disabled=false; } }
function filterTable() { const company = filterCompany.value.toLowerCase(), date = filterDate.value; document.querySelectorAll('#generatedDocsTable tbody tr').forEach(row => row.style.display = (!company || row.cells[1].textContent.toLowerCase().includes(company)) && (!date || row.cells[0].textContent.trim() === date) ? '' : 'none'); } function clearFilters() { filterCompany.value = ''; filterDate.value = ''; filterTable(); } filterCompany.addEventListener('input', filterTable); filterDate.addEventListener('input', filterTable);
document.addEventListener('DOMContentLoaded', () => refreshKsefStatuses(false));
</script>
